UPDATE div_trip_inspection_template_items SET section_name='Mechanical / यांत्रिक', item_no='xvi', label_en='Check intactness of connection strap bolts at all wheels Check Trunion position at all wheels Ensure clearance between connections to guide strip in WAP-1 & WAP-4 locos. Ensure no rubbing of connection strap with wheel of WAP-1 & WAP-4 locos at all wheels Check vertical & lateral play of hangers Check intactness of brake hanger top pin, split pin & safety sling. Check Trunion locking with split pin & proper oiling in WAP-1 & WAP-4 locos. Ensure safety sling for connection strap in WAP-1 & WAP-4 locos.', label_hi='डब्लुएपी 1, डब्लुएपी 4 की ब्रेक रिगिंग क)   सभी व्हिल के कनेक्शन स्ट्रेप बोल्ट का लगा होना सुनिश्चित करे ख)  सभी व्हिल के ट्रा यूनियन की स्थिती की जाॅच करे घ)  डब्लुएपी 1, डब्लुएपी 4 लोको में गाइड स्ट्रिप तथा कनेक्शन के बीच में क्लिअरन्स सुनिश्चित करे । बद्ध ड)  डब्लुएपी 1, डब्लुएपी 4 लोको में सभी व्हिल के कनेक्शन स्ट्रिप का चक्को से ना धिसना सुनिश्चित करे । कद्ध च)  हैंगर में व्हर्टिकल व लेटरल प्ले चेक करे छ)  ब्रेक हॅंगर की टाॅप पिन, स्पलिट पिन, सेफ्टी स्ंिलग का लगे होने की जाॅच करें । ज)  डबलु एपी 1, डबलु एपी 4 लोको में ट्रायूनियन लाॅकिंग स्पलिट पिन व उचित आॅयलिंग की जाॅच करे । हद्ध ह)   डब्लु एपी 1, डब्लु एपी 4 लोको में कनेक्शन स्ट्रिप की सेफ्टी स्ंिलग का होना सुनिश्चित करें । ीद्ध ठतंाम त्पहहपदह व िॅ।च्.1 - ॅ।च्.4ण्', standard_value='Intact Intact Intact Intact Intact Intact Intact Intact', is_required=1 WHERE template_id=346 AND sort_order=110; -- source_row 132
