UPDATE div_trip_inspection_template_items SET section_name='Simulation Mode', item_no='31', label_en='Check the working of the following: No Air leakage from VCB and SR contactors. Working of TE/BE up to Full traction and braking operation. Dropping of TE/BE through RS & A-9. Working of VCD through BPVG, foot switch, BPVR and application of penalty brakes from both cabs.', label_hi='निम्नलिखित की कार्य स्थिति की जांच करें: a) VCB एवं SR कॉन्टैक्टर्स से किसी भी प्रकार का एयर लीकेज न हो।b) पूर्ण ट्रैक्शन एवं ब्रेकिंग ऑपरेशन तक TE/BE का सही तरीके से कार्य करना।c) RS एवं A-9 के माध्यम से TE/BE का ड्रॉप होना।d) BPVG, फुट स्विच, BPVR के माध्यम से VCD का कार्य करना तथा दोनों कैब से पेनाल्टी ब्रेक का लगना।', standard_value='Checked', is_required=1 WHERE template_id=347 AND sort_order=31; -- source_row 46
