UPDATE div_trip_inspection_template_items SET section_name='Pantograph', item_no='viii', label_en='Check upper thrust of both the pantograph. IR03- On 7.0Kgf, Panto pan should not leave OHE while on 7.5Kgf, panto pan should leave OHE by a paper gap between OHE & Panto pan. HRPT- After putting 7.0Kgf, pull the panto pan towards lower side, it must be stop wherever pulling force removed. Similarly, during application of upper force, Panto pan should stop wherever upper force removed.', label_hi='दोनों पेंटोग्राफ के ऊपरी थ्रस्ट की जाँच करें। दोनों पैंटोग्राफ की अपर थ्रस्ट की जांच करें।IR03 - 7.0 किलोग्राम-फोर्स (Kgf) पर पैंटो पैन को ओएचई (OHE) से अलग नहीं होना चाहिए, जबकि 7.5 किलोग्राम-फोर्स (Kgf) पर पैंटो पैन और ओएचई के बीच कागज़ की मोटाई जितना अंतर आ जाना चाहिए।HRPT - 7.0 किलोग्राम-फोर्स (Kgf) लगाने के बाद पैंटो पैन को नीचे की ओर खींचें, खींचने की ताकत हटते ही पैंटो पैन को वहीं रुक जाना चाहिए। इसी प्रकार, जब ऊपर की ओर बल लगाया जाए, तो बल हटते ही पैंटो पैन को वहीं रुक जाना चाहिए।', standard_value='7.0 किलोग्राम 7.0 kgf', is_required=1 WHERE template_id=347 AND sort_order=39; -- source_row 56
UPDATE div_trip_inspection_template_items SET section_name='Main Transformer', item_no='i', label_en='Check the oil level indicator on the both conservators of Transformer and ensure there is no leakage. Ensure Oil level of both conservator of TFP should be between min and max level.', label_hi='ट्रांसफॉर्मर के दोनों कंजरवेटर पर तेल स्तर संकेतक की जांच करें और सुनिश्चित करें कि कोई रिसाव न हो। TFP के दोनों कंजरवेटर का तेल स्तर न्यूनतम और अधिकतम स्तर के बीच होना चाहिए।', standard_value='No Leakage/ level Between min and max', is_required=1 WHERE template_id=347 AND sort_order=46; -- source_row 65
