UPDATE div_trip_inspection_template_items SET section_name='Main Compressor', item_no='ii', label_en='check pipes and support clamps for condition and leakage. Ensure protection guards on compressor are intact & safety slings are fitted on both compressors. Also, visually check compressor fan blades.', label_hi='पाइप्स और सपोर्ट क्लैम्प्स की स्थिति एवं लीकेज की दृश्य जांच करें। सुनिश्चित करें कि कंप्रेसर पर लगे प्रोटेक्शन गार्ड सुरक्षित हैं और दोनों कंप्रेसरों पर सेफ्टी स्लिंग्स लगे हुए हैं। साथ ही, कंप्रेसर के फैन ब्लेड्स की भी दृश्य जांच करें।', standard_value='No Damage/ No Leakage', is_required=1 WHERE template_id=347 AND sort_order=121; -- source_row 161
