UPDATE div_trip_inspection_template_items SET section_name='A-9, SA-9 and RS Valve / A-9, SA-9 और RS वाल्व', item_no='viii', label_en='Apply A9 to full service, the BC pressure should not exceed 2.5kg/cm², Press PVEF, the loco brakes should be released. Apply A9 to emergency, BC pressure should be 2.5 kg/cm², press PVEF, the loco brakes remain in applied condition.', label_hi='लोको ब्रेक्स की संयोजन क्रिया की जांच करें: a) A9 को फुल सर्विस पोजीशन में लगाएं, BC प्रेशर 2.5 kg/cm² से अधिक नहीं होना चाहिए। PVEF दबाएं, लोको ब्रेक्स रिलीज हो जाने चाहिए। b) A9 को इमरजेंसी पोजीशन में लगाएं, BC प्रेशर 2.5 kg/cm² होना चाहिए। PVEF दबाएं, लोको ब्रेक्स लगे हुए ही रहने चाहिए। ंद्ध इद्ध ब्वदरनदबजपवद ूवतापदह व िसवबव इतंामेरू', standard_value='Intact', is_required=1 WHERE template_id=347 AND sort_order=145; -- source_row 191
